sys_variable_value.value:
(function execute(inputs, outputs) {
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Feedback Collection',
        'FEEDBACK_DISPATCH',
        inputs.app_sys_id,
        null,
        'Interview marked COMPLETED',
        'Feedback submission requests created for all panelists (PENDING)',
        null,
        '48-hour feedback deadline active via BR-8'
    );
})(inputs, outputs);

